 "content": "def transform(grid):
    """Decode a grid of repeated motifs arranged in a coarse motif-shaped layout."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The full 3-lines are separators/masks. Record their orientation, then remove them.
    full3_rows = {r for r in range(h) if all(v == 3 for v in grid[r])}
    full3_cols = {c for c in range(w) if all(grid[r][c] == 3 for r in range(h))}

    # Blank gutters (ignoring a full 3-line) reveal the motif stride.
    blank_rows = [r for r in range(h) if r not in full3_rows and
                  all(grid[r][c] == 0 for c in range(w) if c not in full3_cols)]
    blank_cols = [c for c in range(w) if c not in full3_cols and
                  all(grid[r][c] == 0 for r in range(h) if r not in full3_rows)]
    diffs = []
    for seq in (blank_rows, blank_cols):
        diffs.extend(b - a for a, b in zip(seq, seq[1:]) if b > a)
    # In these grids, a repeated blank gutter is one cell wide; stride is motif size + 1.
    if diffs:
        stride = max(set(diffs), key=diffs.count)
    else:
        # Fallback for a grid where only one orientation exposes regular gutters.
        stride = (w + 1) // 3 if w <= 11 else (w + 1) // 4
    tile = stride - 1
    nr = (h + 1) // stride
    nc = (w + 1) // stride
    rstarts = [i * stride for i in range(nr)]
    cstarts = [i * stride for i in range(nc)]

    # The recurring small 2-pattern is the largest non-wall motif tile.
    candidates = []
    for ri, r0 in enumerate(rstarts):
        for ci, c0 in enumerate(cstarts):
            cells = [(r0 + dr, c0 + dc) for dr in range(tile) for dc in range(tile)
                     if r0 + dr < h and c0 + dc < w]
            if any(grid[r][c] == 3 for r, c in cells):
                continue
            count = sum(grid[r][c] == 2 for r, c in cells)
            if count:
                candidates.append((count, ri, ci, cells))
    if not candidates:
        return [[0 if v == 3 else v for v in row] for row in grid]
    _, _, _, exemplar_cells = max(candidates, key=lambda x: x[0])
    mask = [[False] * tile for _ in range(tile)]
    for r, c in exemplar_cells:
        if grid[r][c] == 2:
            mask[r % stride][c % stride] = True

    # For a vertical 3-mask, the small motif is continued into the masked tile
    # locations prescribed by its own coarse arrangement.
    if full3_cols and not full3_rows:
        for ri, r0 in enumerate(rstarts):
            for ci, c0 in enumerate(cstarts):
                if ci >= nc or not all(c in full3_cols for c in range(c0, min(c0 + tile, w))):
                    continue
                for dr in range(tile):
                    for dc in range(tile):
                        rr, cc = r0 + dr, c0 + dc
                        if rr < h and cc < w and mask[ri][ci] and mask[dr][dc]:
                            out[rr][cc] = 2

    # Remove the 3 separator and mark each tile's motif-coordinate pixel.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0
    for ri, r0 in enumerate(rstarts):
        for ci, c0 in enumerate(cstarts):
            occupied = any(out[r0 + dr][c0 + dc] == 2
                           for dr in range(tile) for dc in range(tile)
                           if r0 + dr < h and c0 + dc < w)
            if occupied and ri < tile and ci < tile:
                rr, cc = r0 + ri, c0 + ci
                if rr < h and cc < w and out[rr][cc] == 2:
                    out[rr][cc] = 8
    return out


