 "content": "from math import isqrt


def transform(grid):
    """Reconstruct a self-similarly tiled pattern and mark its diagonal."""
    h, w = len(grid), len(grid[0])
    # n tiles of n cells, separated by single-cell gutters: dimension n*(n+1)-1.
    n = (isqrt(4 * h + 5) - 1) // 2
    if n * (n + 1) - 1 != h or n * (n + 1) - 1 != w:
        raise ValueError("Expected square self-similar tile grid")
    stride = n + 1
    starts = [i * stride for i in range(n)]

    # Find a fully visible tile to use as the repeated local pattern.
    candidates = []
    for ti, r0 in enumerate(starts):
        for tj, c0 in enumerate(starts):
            tile = [row[c0:c0 + n] for row in grid[r0:r0 + n]]
            if any(3 in row for row in tile):
                continue
            count = sum(v == 2 for row in tile for v in row)
            if count:
                candidates.append((count, tile))
    if not candidates:
        raise ValueError("No visible motif tile")
    pattern = max(candidates, key=lambda item: item[0])[1]

    # The motif also defines the occupancy of the coarse tile grid. Reconstruct
    # only the obscured 3-colored tiles whose coarse coordinates are 2 in it.
    out = [[0 if value == 3 else value for value in row] for row in grid]
    for ti, r0 in enumerate(starts):
        for tj, c0 in enumerate(starts):
            present = pattern[ti][tj] == 2
            for dr in range(n):
                for dc in range(n):
                    rr, cc = r0 + dr, c0 + dc
                    if present:
                        out[rr][cc] = pattern[dr][dc]
                    else:
                        out[rr][cc] = 0
            # Mark the motif cell at the coarse tile's coordinates, if present.
            if present and pattern[ti][tj] == 2:
                out[r0 + ti][c0 + tj] = 8
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
