 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find motif size in the repeated arrangement: a size-n motif is repeated
    # on an (n+1)-cell stride, including gutters, and dimensions n(n+1)-1.
    n = next(k for k in range(1, 31) if k * (k + 1) - 1 == h)
    if h != w:
        raise ValueError("Expected square grid")
    stride = n + 1
    starts = [i * stride for i in range(n)]

    # Identify the local motif from the densest fully visible tile.
    tiles = []
    for r0 in starts:
        for c0 in starts:
            vals = [grid[r0 + dr][c0 + dc] for dr in range(n) for dc in range(n)]
            if 3 not in vals:
                tiles.append((vals.count(2), r0, c0))
    _, mr, mc = max(tiles)
    motif = [[grid[mr + dr][mc + dc] for dc in range(n)] for dr in range(n)]

    # The coarse arrangement copies that motif, making the 3-colored region
    # an occlusion. Keep only the motif tiles called for by the coarse mask.
    out = [[0 if value == 3 else value for value in row] for row in grid]
    for tr, r0 in enumerate(starts):
        for tc, c0 in enumerate(starts):
            if motif[tr][tc] != 2:
                continue
            for dr in range(n):
                for dc in range(n):
                    out[r0 + dr][c0 + dc] = motif[dr][dc]

    # Mark as 8 the motif pixels at positions that are 2 in the coarse mask.
    for tr, r0 in enumerate(starts):
        for tc, c0 in enumerate(starts):
            if motif[tr][tc] == 2 and out[r0 + tr][c0 + tc] == 2:
                out[r0 + tr][c0 + tc] = 8
    return out


